BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path=public,extensions;
SELECT plan(17);
INSERT INTO auth.users(id,email) VALUES ('aaaaaaaa-0000-0000-0000-000000000001','atomic1@example.test'),('aaaaaaaa-0000-0000-0000-000000000002','atomic2@example.test');
UPDATE profiles SET plan_tier='premium' WHERE user_id='aaaaaaaa-0000-0000-0000-000000000001';
INSERT INTO baseline_audits(id,user_id,status,completed_at) VALUES('bbbbbbbb-0000-0000-0000-000000000001','aaaaaaaa-0000-0000-0000-000000000001','completed',now());
INSERT INTO strategic_reports(id,user_id,audit_id,edited_ninety_day_plan,pattern_intelligence) VALUES('cccccccc-0000-0000-0000-000000000001','aaaaaaaa-0000-0000-0000-000000000001','bbbbbbbb-0000-0000-0000-000000000001','{"saved":true}','{"exact":true}');
CREATE TEMP TABLE expected AS SELECT to_jsonb(r) AS snapshot FROM strategic_reports r;
SELECT throws_ok($$SELECT archive_and_reset_audit('bbbbbbbb-0000-0000-0000-000000000001')$$,'42501','Authentication required','anonymous rejected');
SELECT set_config('request.jwt.claim.sub','aaaaaaaa-0000-0000-0000-000000000002',true);
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT archive_and_reset_audit('bbbbbbbb-0000-0000-0000-000000000001')$$,'42501','Premium or Coach plan required','free plan rejected');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','aaaaaaaa-0000-0000-0000-000000000001',true);
SET LOCAL ROLE authenticated;
SELECT is(archive_and_reset_audit('bbbbbbbb-0000-0000-0000-000000000001'),1,'archive acknowledged');
SELECT is(archive_and_reset_audit('bbbbbbbb-0000-0000-0000-000000000001'),1,'retry same result');
RESET ROLE;
SELECT is((SELECT report_data FROM audit_history),(SELECT snapshot FROM expected),'entire exact saved report archived');
SELECT is((SELECT count(*) FROM baseline_audits),0::bigint,'audits deleted');
SELECT is((SELECT count(*) FROM strategic_reports),0::bigint,'reports deleted');
SELECT is((SELECT count(*) FROM audit_history),1::bigint,'one history row');
SELECT throws_ok($$SELECT archive_and_reset_audit('bbbbbbbb-0000-0000-0000-000000000002')$$,'42501','Re-audit cooldown is 30 days','cooldown enforced');
CREATE TEMP TABLE payload AS SELECT jsonb_build_object('mood',5,'energy',6,'wins','[]'::jsonb,'blockers','[]'::jsonb,'commitments','[]'::jsonb,'extras','{}'::jsonb,'quick',false,'oneThing','Do the work','reflection','','weekStart',date_trunc('week',now())::date) p;
SELECT lives_ok($$SELECT save_check_in('dddddddd-0000-0000-0000-000000000001',(SELECT p FROM payload))$$,'checkin atomic save');
SELECT lives_ok($$SELECT save_check_in('dddddddd-0000-0000-0000-000000000001',(SELECT p FROM payload))$$,'checkin retry');
SELECT is((SELECT count(*) FROM check_ins),1::bigint,'retry does not duplicate checkin');
SELECT throws_ok($$SELECT save_check_in('dddddddd-0000-0000-0000-000000000002',(SELECT p || '{"mood":11}' FROM payload))$$,'22023','Invalid scale','invalid scalar rejected');
INSERT INTO weekly_commitments(id,user_id,week_start,commitment) VALUES('eeeeeeee-0000-0000-0000-000000000001','aaaaaaaa-0000-0000-0000-000000000002',date_trunc('week',now())::date-7,'Other user');
SELECT throws_ok($$SELECT save_check_in('dddddddd-0000-0000-0000-000000000003',(SELECT p || '{"previousCommitmentId":"eeeeeeee-0000-0000-0000-000000000001","outcome":"yes"}' FROM payload))$$,'42501','Owned previous commitment required','cross-user callback rejected');
UPDATE weekly_commitments SET user_id='aaaaaaaa-0000-0000-0000-000000000001' WHERE id='eeeeeeee-0000-0000-0000-000000000001';
SELECT lives_ok($$SELECT save_check_in('dddddddd-0000-0000-0000-000000000003',(SELECT p || '{"previousCommitmentId":"eeeeeeee-0000-0000-0000-000000000001","outcome":"yes"}' FROM payload))$$,'owned callback saved');
SELECT is((SELECT outcome FROM weekly_commitments WHERE id='eeeeeeee-0000-0000-0000-000000000001'),'yes','outcome updated');
SELECT is((SELECT count(*) FROM commitment_callbacks),1::bigint,'callback row persisted');
SELECT * FROM finish();
ROLLBACK;
